from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/1975641/000121390026048584/ea0287565-20f_zhengye.htm','Issuer 2025 annual report filed April 2026: product table, regulatory table and development discussion manually reviewed. Duplicate duck-plague entries consolidated; government-procurement classical-swine-fever variant held pending distinct formulation evidence. Rabies expressly production-ready with future launch despite inclusion in marketed table. Haemophilus row indication conflicts with antigen identity; conflicting indication not copied.')
products=[]
for row in json.loads((out/'zhengye-reviewed-table.json').read_text()):
 n=' '.join(row['name'].split()).replace('Cirovirus','Circovirus')
 if n in ['Duck plague live vaccine','Swine Fever Vaccine, only for Government Procurement, Live (Tissue Culture Origin)']:continue
 life='unknown' if n.startswith('Rabies Vaccine') else 'commercial'
 products.append(p('Zhengye '+n,'Veterinary vaccine; target species: '+row['species']+'.'+(' Production-ready; market launch not established.' if life=='unknown' else ''),a,life,roles=['commercial_partner'],typ='product',territory='China',attributes={'export_markets':[] if row['exports']=='N/A' else row['exports'].split(', '),'operating_entity':'Jilin Zhengye Biological Products Co., Ltd.'}))
pipeline=[('Thermostable Newcastle disease/infectious bronchitis live vaccine (LaSota + SZ160)','development'),('Porcine circovirus type 2/Mycoplasma combined inactivated vaccine (ZSTU01 + MH03)','development'),('Newcastle disease/avian influenza H9/avian adenovirus vaccine (aSG10 + G + Fiber-2)','development'),('Feline panleukopenia/calicivirus/rhinotracheitis triple inactivated vaccine','development'),('Canine distemper/parvovirus inactivated vaccine','development'),('GnRH companion-animal immunocontraceptive vaccine','research')]
products += [p('Zhengye '+n,'Veterinary vaccine programme. Registration, clinical completion or production approval discussed in annual report; projected milestones not treated as achieved.',a,life,roles=['commercial_partner'],territory='China') for n,life in pipeline]
b=ev('https://www.jlzybio.com/科技领航，正业担当-热烈祝贺正业生物pcv3型亚单位/','January 15, 2026 official research announcement: PCV3 antigen process development and five co-participating provincial research projects. Future clinical application is not actual clinical dosing; jointly participating does not establish exclusive ownership.')
research=[('PCV3 subunit vaccine','Porcine circovirus type 3 vaccine research.'),('Feline conjunctivitis/rhinotracheitis bivalent recombinant live-vector vaccine','Joint feline vaccine research.'),('Recombinant Orf virus mammary-tumour programme','Joint veterinary tumour-therapy research.'),('Avian ferritin multivalent nanoparticle vaccine','Joint poultry vaccine research.'),('Bovine enterotoxigenic E. coli/Clostridium perfringens bivalent vaccine','Joint bovine vaccine research.'),('Porcine epidemic-diarrhoea multi-epitope nanoparticle vaccine','Joint swine vaccine research.')]
products += [p('Zhengye '+n,d,b,'research',roles=['commercial_partner']) for n,d in research]
co=dict(company_id='cmp_14bfabb1-7dee-485e-bd1c-498639830a19',products=products,evidence=[a],status='partial',coverage_note='Annual-report 50-row product table consolidated to 48 records plus six distinct development programmes. Rabies launch uncertainty retained. Partial: current Chinese catalogue specifications, PCV3 research, approval-table-only legacy entries, and latest production/launch updates require follow-up. No presumed new-product identity for duplicate duck-plague or procurement-only entries; no presumed distinct second feline triple-vaccine wording. Parent relationship is commercial partner; vaccines manufactured by operating subsidiary.')
co['evidence'].append(b)
co['coverage_note']=co['coverage_note'].replace('PCV3 research, ','').replace('plus six distinct development programmes','plus six distinct development programmes and six research projects')
(out/'batch-0273.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
